export interface ResumableJob {
  id: string;
  displayId: string;
  startedAt: string;
  sourcesTotal: number;
  sourcesCompleted: number;
  stale: boolean;
}

export interface ResumeJobRequest {
  /** uuid or display id (e.g. collect-000123); omit to resume the most recent non-stale interrupted job */
  jobId?: string;
}

export type BackupRunStatus = typeof BackupRunStatus[keyof typeof BackupRunStatus];


export const BackupRunStatus = {
  running: 'running',
  completed: 'completed',
  failed: 'failed',
} as const;

export interface BackupRun {
  id: string;
  status: BackupRunStatus;
  startedAt: string;
  /** @nullable */
  endedAt: string | null;
  /** @nullable */
  filePath: string | null;
  /** @nullable */
  sizeBytes: number | null;
  /** @nullable */
  errorMessage: string | null;
}

export interface RestoreBackupRequest {
  /** backup_runs.id from GET /backups — NOT a filesystem path. The server looks up the real file path itself; a client can only pick which recorded backup to restore, never point pg_restore at an arbitrary file. */
  id: string;
  /** must be true — a lightweight guard against an accidental restore call, mirroring the CLI's --yes flag */
  confirm: boolean;
}

/**
 * Block/table counts by RIR, family, and status, plus last-run-per-source — same content as `ip-insight summary`. Loosely typed (additionalProperties) since it's a nested, evolving breakdown shown read-only in the panel.
 */
export interface DatabaseSummary { [key: string]: unknown }

